-- Queer Atlas: Thessaloniki city package
-- Editorially checked 2026-08-13. Idempotent; no null coordinates.

begin;

with src as (
select * from jsonb_to_recordset($json$
[
 {"name":"Enola Bar Club","city":"thessaloniki","type":"club","description":"Thessaloniki's longest-running visible LGBTQ+ club, open since 2008 on the second floor of a Valaoritou gallery. Wednesday leans into Greek music; Friday and Saturday bring dance sets, hosts and short drag appearances. The room helped incubate the first organising meeting that became Thessaloniki Pride, so its place in the city is social as well as nocturnal.","vibe":"late, colourful queer anchor with Greek-pop nights and weekend drag","hours":"Every night from 23:30; special-event opening, cover and closing time vary.","link":"https://enola.gr/","location":"Valaoritou 19, 2nd floor, 546 25 Thessaloniki, Greece","lat":40.63712,"lng":22.93941},
 {"name":"XPOSE Club","city":"thessaloniki","type":"club","description":"A spacious LGBTQ+ weekend club where mixed dance music and drag carry the room into early morning. Visitors repeatedly describe an easy welcome across queer identities and women as well as men; the practical rhythm is later than a bar, with the floor usually waking after 01:00 rather than at doors.","vibe":"big-hearted weekend dance floor with drag and a younger mixed queer crowd","hours":"Usually Friday and Saturday 23:58-06:00; verify the current Instagram programme.","link":"https://www.instagram.com/xpose.skg/","location":"Politechniou 31, 546 26 Thessaloniki, Greece","lat":40.63704,"lng":22.93403},
 {"name":"PLAY Thessaloniki","city":"thessaloniki","type":"cruise_club","description":"A men-focused adult cruise and fetish club arranged across three levels, with maze, cabins, sling, darkroom features and a connected adult shop. Attendance changes sharply by hour, and membership decisions have drawn conflicting visitor reports, so confirm access directly before building a night around it.","vibe":"multi-level men-focused cruise club where timing matters more than spectacle","hours":"Published directory hours: Monday-Thursday 10:00-02:00, Friday-Saturday 10:00-04:00, Sunday 09:00-01:00; confirm directly.","link":"https://www.travelgay.com/venue/play","location":"Odisseos 13, 546 29 Thessaloniki, Greece","lat":40.64406,"lng":22.93289},
 {"name":"Splash Sauna Thessaloniki","city":"thessaloniki","type":"sauna","description":"The current iteration of Thessaloniki's men-focused gay sauna, now listed at Tantalou 29-31 rather than the older addresses still circulating online. Steam, dry sauna, pool and adult relaxation areas share a compact, recently refreshed space. Fresh 2026 feedback praises cleanliness and warm reception while also noting that water temperature, smoke and crowd size can vary.","vibe":"freshly renewed gay sauna with friendly reception and a weekend-weighted crowd","hours":"Monday-Thursday and Sunday 14:00-03:00; Friday-Saturday 14:00-07:00 according to the current July 2026 listing. Confirm same-day.","link":"https://www.gayout.com/europe/greece/thessaloniki/saunas/splash-sauna-1003","location":"Tantalou 29-31, Thessaloniki, Greece","lat":40.64474,"lng":22.93218},
 {"name":"Iliotropio Cafe","city":"thessaloniki","type":"cafe","description":"A long-lived Navarinou cafe with board games, inexpensive drinks and an alternative crowd that local queer recommendations return to again and again. It is LGBTQ-friendly rather than exclusively queer: useful for a daytime date, a low-pressure first meeting or conversation before the clubs, not a substitute for a programmed queer night.","vibe":"studenty queer-friendly living room with games, snacks and long conversations","hours":"Generally daily 09:00-01:00; holiday service may change.","link":"https://www.facebook.com/pages/iliotropio-cafe/194497327264032","location":"Platia Navarinou 14, 546 22 Thessaloniki, Greece","lat":40.6310204,"lng":22.9489985},
 {"name":"Ypsilon","city":"thessaloniki","type":"cafe","description":"A restored 1868 townhouse working as cafe, bar, workspace and cultural venue. Ypsilon is not a permanent gay bar, but queer readings, Pride screenings and independent events repeatedly make it part of the real social map. Come for the programme or for a beautifully designed all-day room; do not assume every late set has the same audience.","vibe":"design-led cultural house where daytime laptops give way to independent nights","hours":"Generally daily from 09:00 until late; current listings vary between midnight and 03:00 by day, so check the programme.","link":"https://www.facebook.com/ypsilonproject/","location":"Edessis 5, 546 25 Thessaloniki, Greece","lat":40.63655,"lng":22.93761},
 {"name":"Rediviva Cucina Povera","city":"thessaloniki","type":"restaurant","description":"A worker-led social cooperative in Ano Poli turning humble seasonal ingredients into thoughtful Greek small plates, with strong vegetarian and vegan choices. Queer locals recommend it as an easy date or mixed-group dinner rather than a branded scene venue. The uphill neighbourhood, courtyard and regulars-first atmosphere make it feel distinctly Thessalonian.","vibe":"warm cooperative kitchen for slow queer-friendly dinners above the centre","hours":"Monday and Wednesday-Thursday 14:00-00:00; Friday-Saturday until about 00:30; Sunday 13:00-22:00; Tuesday closed.","link":"https://www.rediviva.gr/","location":"Alexandras Papadopoulou 70, 546 33 Thessaloniki, Greece","lat":40.64287,"lng":22.95363},
 {"name":"ONOMA Hotel","city":"thessaloniki","type":"hotel","description":"A playful design hotel by the railway station that has repeatedly hosted Pride programming and appears among Thessaloniki Pride's hospitality partners. Its rooftop, games and social spaces suit travellers who want personality and quick access to Vardaris and Valaoritou, though the station-side setting is less romantic than the waterfront.","vibe":"techy Pride-supporting hotel with a sociable roof and western-centre access","hours":"Hotel reception operates 24 hours; rooftop, pool, food and visitor access follow seasonal schedules.","link":"https://onomahotel.com/","location":"Monastiriou 24, 546 29 Thessaloniki, Greece","lat":40.64204,"lng":22.93173}
]
$json$) p(name text,city text,type text,description text,vibe text,hours text,link text,location text,lat double precision,lng double precision)
), upd as (
 update public.places p set type=s.type,description=s.description,vibe=s.vibe,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
 from src s where lower(trim(p.city))=s.city and lower(trim(p.name))=lower(trim(s.name)) returning p.id
)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,seo_indexable,seo_quality_status,updated_at)
select name,city,type,description,vibe,array[]::text[],hours,link,location,lat,lng,true,'approved',timezone('utc',now()) from src s
where not exists(select 1 from public.places p where lower(trim(p.city))=s.city and lower(trim(p.name))=lower(trim(s.name)));

with src as (
select * from jsonb_to_recordset($json$
[
 {"name":"Thessaloniki Pride 2026","city":"thessaloniki","description":"The fourteenth Pride ran under the theme Break the Code with six days of literature, workshops, film, advocacy and nightlife. On 20 June the march left White Tower Square at 18:30, looped through the centre and waterfront, and returned for a public concert until midnight.","link":"https://thessalonikipride.com/program-of-the-festival/?lang=en","date":"2026-06-15","start_date":"2026-06-15","end_date":"2026-06-20","location":"White Tower Square and venues across central Thessaloniki, Greece","lat":40.62642,"lng":22.94839,"vibe":"civic, political and joyful Pride week ending on the waterfront"},
 {"name":"Self-Organised Thessaloniki Pride 2026","city":"thessaloniki","description":"The tenth self-organised Pride kept a sponsor-free, movement-led current visible alongside the city's institutional festival. Its colourful march gathered at the Venizelos statue on 23 May, foregrounding community control, free expression and solidarity rather than a commercial Pride format.","link":"https://www.thestival.gr/eidiseis/koinonia/thessaloniki-simera-i-polychromi-porei-2/","date":"2026-05-23","start_date":"2026-05-23","end_date":"2026-05-23","location":"Venizelos Statue, Egnatia, Thessaloniki, Greece","lat":40.63747,"lng":22.94423,"vibe":"grassroots, anti-commercial Pride shaped through open assembly"},
 {"name":"Love Unbound: Five Films For Freedom 2026","city":"thessaloniki","description":"A free two-day LGBTQIA+ festival at Beetroot House combining the British Council and BFI Flare shorts with Greek work, talks, workshops and photography. The small-scale format made identity, gender and visibility discussable rather than packaging queer cinema as a single screening.","link":"https://www.britishcouncil.gr/en/events/love-unbound-five-films-for-freedom","date":"2026-03-20","start_date":"2026-03-20","end_date":"2026-03-21","location":"Beetroot House, Siggrou 8, 546 25 Thessaloniki, Greece","lat":40.63736,"lng":22.93886,"vibe":"free queer short film, conversation and intimate cultural exchange"},
 {"name":"SmaDragdus at Thessaloniki Fringe 2026","city":"thessaloniki","description":"A confirmed cabaret in the 2026 Thessaloniki Fringe programme, playing at Transcendance on 8 and 9 October at 22:00. It places drag inside an international independent-performance festival rather than a standard nightclub set; buy for the show and arrive as theatre audience, not for an open-ended party.","link":"https://thessfringe.com/","date":"2026-10-08","start_date":"2026-10-08","end_date":"2026-10-09","location":"Transcendance, Polyxenis Antoniou 4, 546 32 Thessaloniki, Greece","lat":40.64329,"lng":22.95584,"vibe":"late independent drag cabaret for a curious Fringe crowd"}
]
$json$) e(name text,city text,description text,link text,date date,start_date date,end_date date,location text,lat double precision,lng double precision,vibe text)
), upd as (
 update public.events e set description=s.description,link=s.link,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
 from src s where lower(trim(e.city))=s.city and lower(trim(e.name))=lower(trim(s.name)) returning e.id
)
insert into public.events(name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],true,'approved',timezone('utc',now()) from src s
where not exists(select 1 from public.events e where lower(trim(e.city))=s.city and lower(trim(e.name))=lower(trim(s.name)));

with src as (
select * from jsonb_to_recordset($json$
[
 {"name":"Thess Checkpoint","city":"thessaloniki","type":"wellness","provider_name":"Positive Voice Greece","contact":"+30 2310 282284","booking_link":"https://mycheckpoint.gr/","description":"Community-based, confidential rapid testing and counselling for HIV and other sexually transmitted infections, designed to lower the friction and stigma of clinical testing. Call or use the current booking route because official public-health documents and older campaign material show different Egnatia street numbers.","hours":"Current appointment schedule should be confirmed directly; published campaign material has listed Tuesday-Saturday 12:00-20:00.","link":"https://mycheckpoint.gr/","location":"Egnatia, central Thessaloniki, Greece - confirm the current number when booking","lat":40.63318,"lng":22.95466,"price_tier":"$","vibe":"low-threshold queer sexual-health testing with privacy at the centre","source":"Greek National Public Health Organization testing directory and Thess Checkpoint; checked 2026-08-13"},
 {"name":"PRAKSIS Thessaloniki Polyclinic","city":"thessaloniki","type":"wellness","provider_name":"PRAKSIS","contact":"+30 2310 556145","booking_link":"https://praksis.gr/","description":"A community polyclinic included in Greece's public-health directory for free anonymous rapid HIV testing, with wider support for people facing exclusion. This is a mixed service rather than an LGBTQ-only clinic; call first for the live test window and the right entrance.","hours":"Testing and clinic sessions by current programme or appointment; telephone confirmation required.","link":"https://praksis.gr/","location":"Arkadioupoleos 1 and Agiou Dimitriou, Thessaloniki, Greece","lat":40.64624,"lng":22.92962,"price_tier":"$","vibe":"practical anonymous testing inside a broader social-health network","source":"Greek National Public Health Organization HIV testing structures; checked 2026-08-13"},
 {"name":"11528 By Your Side","city":"thessaloniki","type":"wellness","provider_name":"11528","contact":"Call 11528","booking_link":"https://11528.gr/","description":"Greece's specialist support line for lesbian, gay, bisexual, trans, queer and questioning people, families and professionals. It is useful from Thessaloniki without exposing a protected local address: begin by phone for confidential listening, information and referral instead of arriving at an invented walk-in office.","hours":"Use the current hours published on the official service before calling; not an emergency line.","link":"https://11528.gr/","location":"National remote service available in Thessaloniki, Greece","lat":40.64010,"lng":22.94440,"price_tier":"$","vibe":"private first contact for identity, family pressure and informed referral","source":"11528 official service; checked 2026-08-13"},
 {"name":"Thessaloniki Pride Community Organisation","city":"thessaloniki","type":"other","provider_name":"Thessaloniki Pride","contact":"contact@thessalonikipride.com","booking_link":"https://thessalonikipride.com/epikinonia/","description":"The year-round organisation behind the city's annual Pride, with education, cultural programming, advocacy, volunteering and international community links. Contact by purpose rather than expecting a public daily centre: participation, non-profit collaboration and commercial partnership use different routes.","hours":"Organisation and volunteering by programme or appointment; no dependable daily public walk-in hours are published.","link":"https://thessalonikipride.com/?lang=en","location":"Thessaloniki, Greece - meeting venue supplied for each programme","lat":40.64010,"lng":22.94440,"price_tier":"$","vibe":"year-round Pride infrastructure connecting visibility, learning and action","source":"Thessaloniki Pride official contact, programme and European Youth Portal profile; checked 2026-08-13"}
]
$json$) s(name text,city text,type text,provider_name text,contact text,booking_link text,description text,hours text,link text,location text,lat double precision,lng double precision,price_tier text,vibe text,source text)
), upd as (
 update public.services x set type=s.type,provider_name=s.provider_name,contact=s.contact,booking_link=s.booking_link,description=s.description,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,price_tier=s.price_tier,vibe=s.vibe,source=s.source,"lastChecked"='2026-08-13'::date,verified=true,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
 from src s where lower(trim(x.city))=s.city and lower(trim(x.name))=lower(trim(s.name)) returning x.id
)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,image_urls,location,lat,lng,price_tier,vibe,vibe_tags,source,"lastChecked",verified,seo_indexable,seo_quality_status,updated_at)
select name,city,type,provider_name,contact,booking_link,description,hours,link,array[]::text[],location,lat,lng,price_tier,vibe,array[]::text[],source,'2026-08-13'::date,true,true,'approved',timezone('utc',now()) from src s
where not exists(select 1 from public.services x where lower(trim(x.city))=s.city and lower(trim(x.name))=lower(trim(s.name)));

commit;

select 'places' category,count(*) total from public.places where lower(trim(city))='thessaloniki'
union all select 'events',count(*) from public.events where lower(trim(city))='thessaloniki'
union all select 'services',count(*) from public.services where lower(trim(city))='thessaloniki'
order by category;
